const secret = $json.headers['x-telegram-bot-api-secret-token'];
const expected = $env.TELEGRAM_WEBHOOK_SECRET;

function timingSafeEqualStr(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) result |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return result === 0;
}

const validSecret = !!expected && timingSafeEqualStr(secret, expected);

const update = $json.body || {};
const message = update.message;
const hasText = !!(message && message.from && typeof message.text === 'string');

if (!validSecret || !hasText) {
  return [{ json: { valid: false } }];
}

return [{
  json: {
    valid: true,
    platform: 'telegram',
    platform_user_id: String(message.from.id),
    chat_id: String(message.chat.id),
    platform_message_id: String(update.update_id),
    text: message.text,
    received_at: new Date(message.date * 1000).toISOString(),
    // when our own pipeline started, distinct from received_at (when Telegram says the user
    // sent it) - used to compute latency_ms at the final interaction_logs insert
    processing_started_at: new Date().toISOString(),
    // lets a later "feedback 1"/"feedback 0" reply be matched back to the specific answer
    // being rated via platform_response_message_id, not just "whatever this user asked most
    // recently"
    reply_to_message_id: message.reply_to_message ? String(message.reply_to_message.message_id) : null,
  },
}];

// The redis incr operation returns { json: { [theKeyName]: incrementVal } } - the property
// name IS the literal Redis key (dynamic, includes platform_user_id), not a fixed field.
// Normalize into a fixed field name so the next IF node has something stable to check.
// If Redis was unavailable, "Check Rate Limit" failed open (continueRegularOutput) and
// $json is empty here - Object.values(...)[0] is then undefined, and Number(undefined) is
// NaN, which fails every comparison in the next IF node, so we default to 0 (not over limit).
const count = Object.values($json)[0];
return [{ json: { rate_limit_count: Number(count) || 0 } }];

const text = $('Verify & Normalize').item.json.text || '';
const match = text.match(/^feedback\s+([01])$/i);
const score = match ? parseInt(match[1], 10) : null;
return [{ json: { feedback_score: score } }];

const text = $('Verify & Normalize').item.json.text;

// --- language detection (mirrors shared/language-detect.ts) ---
const HEBREW_RANGE = /[\u0590-\u05FF]/;
const language = HEBREW_RANGE.test(text) ? 'he' : 'en';

// --- classification stub (mirrors security/classification/classify.ts) ---
// Always PUBLIC for now - see the comment in that file for why. Not a real control yet;
// the sensitive-data detector below is the real control at this phase.
const classification = 'PUBLIC';

// --- sensitive-data detection (mirrors security/sensitive-data-detection/*.ts) ---
const PATTERNS = [
  { id: 'openai-api-key', category: 'credential', regex: /\bsk-\s?[A-Za-z0-9]{20,}\b/ },
  { id: 'aws-access-key-id', category: 'credential', regex: /\bAKIA[0-9A-Z]{16}\b/ },
  { id: 'google-api-key', category: 'credential', regex: /\bAIza[0-9A-Za-z_-]{35}\b/ },
  { id: 'bearer-token', category: 'credential', regex: /\bBearer\s+[A-Za-z0-9._-]{20,}\b/i },
  { id: 'generic-secret-assignment', category: 'credential', regex: /\b(api[_-]?key|secret|token|password|passwd|pwd)\b\s*[:=]\s*['"]?[^\s'"]{6,}['"]?/i },
  { id: 'private-key-block', category: 'credential', regex: /-----BEGIN\s+(RSA|EC|OPENSSH|DSA)?\s*PRIVATE KEY-----/ },
  { id: 'email-address', category: 'personal_identifier', regex: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/ },
  { id: 'credit-card-like-number', category: 'personal_identifier', regex: /\b(?:\d[ -]?){13,19}\b/ },
  { id: 'private-ipv4', category: 'internal_network', regex: /\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3})\b/ },
];

function redact(t, match) {
  const start = match.index;
  const end = start + match[0].length;
  const before = t.slice(Math.max(0, start - 15), start);
  const after = t.slice(end, end + 15);
  return (before + '*'.repeat(Math.min(match[0].length, 12)) + after).trim();
}

let sensitiveResult = { flagged: false };
for (const p of PATTERNS) {
  const m = text.match(p.regex);
  if (m) {
    sensitiveResult = { flagged: true, category: p.category, detector: p.id, redactedExcerpt: redact(text, m) };
    break;
  }
}

return [{
  json: {
    language,
    classification,
    sensitive_flagged: sensitiveResult.flagged,
    sensitive_category: sensitiveResult.category || null,
    sensitive_detector: sensitiveResult.detector || null,
    sensitive_redacted_excerpt: sensitiveResult.redactedExcerpt || null,
  },
}];

const text = $('Verify & Normalize').item.json.text || '';

let historyMessages = [];
try {
  const raw = $('Load Conversation History').item.json.history_raw;
  if (raw) {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) historyMessages = parsed;
  }
} catch (e) { historyMessages = []; }

// Semantic-cache eligibility per PROJECT-SPEC.md §9: "no personalized context" (only a fresh
// conversation, no prior turns) and "no time-sensitive question". Gates both the cache lookup
// (Search Semantic Cache) and the cache write (Determine Should Cache reuses this same value).
const TIME_SENSITIVE = /today|now|latest|current|this week|היום|עכשיו|אחרון|השבוע/i;
const cacheEligible = historyMessages.length === 0 && !TIME_SENSITIVE.test(text);

return [{ json: { cache_eligible: cacheEligible } }];

const chatId = $('Verify & Normalize').item.json.chat_id;
const cache = $json;

return [{
  json: {
    chat_id: chatId,
    text: cache.response_text,
    agent_response: cache.response_text,
    routed_model: cache.routed_model,
    input_tokens: 0,
    output_tokens: 0,
    cost_usd: 0,
    intent: cache.intent + '_cached',
    retrieved_kb_ids: JSON.stringify(cache.retrieved_kb_ids || []),
    prompt_version_id: null,
    cache_hit: true,
    cached_input_tokens: cache.input_tokens || null,
    // no fresh Security Prompt call runs on a cache hit (see the pipeline diagram note in
    // CLAUDE.md) - null here, not a stale/reused value from whatever generated the cached
    // response originally.
    security_signal: null,
    security_signal_reasoning: null,
  },
}];

const raw = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

// Fail toward today's pre-router behavior, not toward blocking: 'question'/'simple'/needs_kb
// true means "trust a real KB match if one exists, otherwise treat as ordinary Tier 1".
const intent = (parsed && parsed.intent) || 'question';
const complexity = (parsed && parsed.complexity) || 'simple';
const needsKb = parsed && typeof parsed.needs_kb === 'boolean' ? parsed.needs_kb : true;

return [{ json: { intent, complexity, needs_kb: needsKb } }];

const raw = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

// Advisory only (see database/seed/security-prompt.sql) - fail toward today's behavior
// (PUBLIC, unchanged gate), never toward blocking, if the classification call itself fails.
const VALID = ['PUBLIC', 'INTERNAL', 'SENSITIVE', 'CLASSIFIED'];
const securitySignal = parsed && VALID.includes(parsed.classification) ? parsed.classification : 'PUBLIC';
const securitySignalReasoning = (parsed && parsed.reasoning) || null;

return [{ json: { security_signal: securitySignal, security_signal_reasoning: securitySignalReasoning } }];

// Cosine distance: 0 = identical, 2 = opposite. Start conservative - tune with real
// usage data, same principle PROJECT-SPEC.md §9 applies to semantic cache thresholds.
const DISTANCE_THRESHOLD = 0.5;

const results = $input.all();
const best = results.length > 0 ? results[0].json : null;

if (best && best.distance < DISTANCE_THRESHOLD) {
  return [{
    json: {
      matched: true,
      matched_id: best.id,
      title: best.title,
      url: best.url,
      summary_he: best.summary_he,
      summary_en: best.summary_en,
      distance: best.distance,
    },
  }];
}

return [{ json: { matched: false } }];

const b = $json;
const monthlyBudget = Number(b.monthly_budget_usd) || 0;
const dailyBudget = Number(b.daily_budget_usd) || 0;
const warningThreshold = Number(b.warning_threshold) || 0;
const hardStopThreshold = Number(b.hard_stop_threshold) || 0;
const monthCost = Number(b.month_cost) || 0;
const todayCost = Number(b.today_cost) || 0;

if (!monthlyBudget || !dailyBudget || !warningThreshold || !hardStopThreshold) {
  return [{ json: { budget_state: 'HARD_STOP', month_cost: monthCost, today_cost: todayCost, monthly_budget_usd: monthlyBudget, daily_budget_usd: dailyBudget } }];
}

const RESTRICTED_THRESHOLD = 0.9;
const fraction = Math.max(monthCost / monthlyBudget, todayCost / dailyBudget);

let budgetState;
if (fraction >= hardStopThreshold) budgetState = 'HARD_STOP';
else if (fraction >= RESTRICTED_THRESHOLD) budgetState = 'RESTRICTED';
else if (fraction >= warningThreshold) budgetState = 'WARNING';
else budgetState = 'NORMAL';

return [{ json: { budget_state: budgetState, month_cost: monthCost, today_cost: todayCost, monthly_budget_usd: monthlyBudget, daily_budget_usd: dailyBudget } }];

const budgetState = $('Budget Guard').item.json.budget_state;
const match = $('Pick Best Match').item.json;
// Real intent router (Phase 7 gap 3/3) replaces the old regex/length heuristic entirely -
// its own "Parse Intent" try/catch already provides the fallback path if the classification
// call itself fails, so no second fallback heuristic is kept here.
const parsedIntent = $('Parse Intent').item.json;
if (budgetState === 'HARD_STOP') return [{ json: { tier: 'tier0' } }];
// Trust Pick Best Match's own similarity search alone for the tier0 short-circuit, not
// needs_kb - tried gating this on needs_kb too and it suppressed a real, reliable match
// (the router's judgment call is less trustworthy here than RAG's own distance threshold).
// needs_kb still flows into logging (see Format Tier0 Response) as a descriptive signal.
if (match.matched) return [{ json: { tier: 'tier0' } }];
if (budgetState === 'RESTRICTED') return [{ json: { tier: 'tier1' } }];
return [{ json: { tier: parsedIntent.complexity === 'complex' ? 'tier2' : 'tier1' } }];

const chatId = $('Verify & Normalize').item.json.chat_id;
const language = $('Detect Language, Classify, Detect Sensitive Data').item.json.language;
const match = $('Pick Best Match').item.json;
const budgetState = $('Budget Guard').item.json.budget_state;
const parsedIntent = $('Parse Intent').item.json;

let text, intent;
if (match.matched) {
  text = language === 'he'
    ? `מצאתי את זה: *${match.title}*\n${match.summary_he}\n${match.url}`
    : `Here's what I found: *${match.title}*\n${match.summary_en}\n${match.url}`;
  intent = 'kb_match_' + parsedIntent.intent;
} else if (budgetState === 'HARD_STOP') {
  text = language === 'he'
    ? 'הגעתי למגבלת השימוש היומית שלי. נסה שוב מאוחר יותר.'
    : "I've hit today's usage limit. Please try again later.";
  intent = 'budget_hard_stop';
} else {
  text = language === 'he'
    ? 'עדיין אין לי משהו ספציפי על זה במאגר הידע שלי.'
    : "I don't have anything specific on that yet in my knowledge base.";
  intent = 'no_match_' + parsedIntent.intent;
}

// retrieved_kb_ids/prompt_version_id/cache_hit/cached_input_tokens: part of the common leaf
// shape all 4 leaves feeding "Build Conversation Update" must emit (see the "why this shape"
// note on that node) - Insert interaction_logs (final) reads these only through Build
// Conversation Update, never directly from Pick Best Match/Get System Prompt, since those
// aren't valid ancestors on every leaf's path (e.g. a cache-hit item never runs either node).
const retrievedKbIds = JSON.stringify(match.matched ? [match.matched_id] : []);
const promptVersionId = $('Get System Prompt').item.json.id;
const securitySignal = $('Parse Security Signal').item.json;

return [{ json: { chat_id: chatId, text, agent_response: text, routed_model: 'none', input_tokens: 0, output_tokens: 0, cost_usd: 0, intent, retrieved_kb_ids: retrievedKbIds, prompt_version_id: promptVersionId, cache_hit: false, cached_input_tokens: null, security_signal: securitySignal.security_signal, security_signal_reasoning: securitySignal.security_signal_reasoning } }];

const text = $('Verify & Normalize').item.json.text;
const language = $('Detect Language, Classify, Detect Sensitive Data').item.json.language;
const match = $('Pick Best Match').item.json;
const promptRow = $('Get System Prompt').item.json;

let historyMessages = [];
try {
  const raw = $('Load Conversation History').item.json.history_raw;
  if (raw) {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) historyMessages = parsed;
  }
} catch (e) { historyMessages = []; }

let systemText = (promptRow && promptRow.prompt_text) || '';
if (match && match.matched) {
  const context = language === 'he' ? match.summary_he : match.summary_en;
  systemText += `\n\nRelevant knowledge base context you can use if helpful (title: "${match.title}", url: ${match.url}):\n${context}`;
}

return [{ json: { system_text: systemText, history_messages: historyMessages, user_text: text } }];

