const resp = $json;
const text = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
const inputTokens = (resp.usage && resp.usage.prompt_tokens) || 0;
const outputTokens = (resp.usage && resp.usage.completion_tokens) || 0;

const pricingRows = $('Get Model Pricing').all().map(i => i.json);
const pricing = pricingRows.find(r => r.model_name === 'gpt-5.4-nano') || {};
const inputPrice = Number(pricing.input_price_per_1m_tokens) || 0;
const outputPrice = Number(pricing.output_price_per_1m_tokens) || 0;
const costUsd = (inputTokens / 1e6) * inputPrice + (outputTokens / 1e6) * outputPrice;

// mirrors security/sensitive-data-detection/*.ts - same list as the input-side check in
// "Detect Language, Classify, Detect Sensitive Data" above, copied here for the output side
const PATTERNS = [
  { id: 'openai-api-key', category: 'credential', regex: /\bsk-\s?[A-Za-z0-9]{20,}\b/ },
  { id: 'aws-access-key-id', category: 'credential', regex: /\bAKIA[0-9A-Z]{16}\b/ },
  { id: 'google-api-key', category: 'credential', regex: /\bAIza[0-9A-Za-z_-]{35}\b/ },
  { id: 'bearer-token', category: 'credential', regex: /\bBearer\s+[A-Za-z0-9._-]{20,}\b/i },
  { id: 'generic-secret-assignment', category: 'credential', regex: /\b(api[_-]?key|secret|token|password|passwd|pwd)\b\s*[:=]\s*['"]?[^\s'"]{6,}['"]?/i },
  { id: 'private-key-block', category: 'credential', regex: /-----BEGIN\s+(RSA|EC|OPENSSH|DSA)?\s*PRIVATE KEY-----/ },
  { id: 'email-address', category: 'personal_identifier', regex: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/ },
  { id: 'credit-card-like-number', category: 'personal_identifier', regex: /\b(?:\d[ -]?){13,19}\b/ },
  { id: 'private-ipv4', category: 'internal_network', regex: /\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3})\b/ },
];
let flagged = false;
for (const p of PATTERNS) { if (p.regex.test(text)) { flagged = true; break; } }

const language = $('Detect Language, Classify, Detect Sensitive Data').item.json.language;
const chatId = $('Verify & Normalize').item.json.chat_id;
const parsedIntent = $('Parse Intent').item.json;

let finalText = text, intent = 'generated_tier1_' + parsedIntent.intent;
if (!text || flagged) {
  intent = flagged ? 'output_blocked_sensitive_data' : 'generation_empty';
  finalText = language === 'he'
    ? 'מצטער, לא הצלחתי לייצר תשובה בטוחה כרגע. נסה לנסח את השאלה מחדש.'
    : "Sorry, I couldn't generate a safe response right now. Try rephrasing your question.";
}

// see the matching comment in "Format Tier0 Response" for why these four fields are computed
// here rather than referenced later from Pick Best Match/Get System Prompt directly
const retrievedKbIds = JSON.stringify($('Pick Best Match').item.json.matched ? [$('Pick Best Match').item.json.matched_id] : []);
const promptVersionId = $('Get System Prompt').item.json.id;
const securitySignal = $('Parse Security Signal').item.json;

return [{ json: { chat_id: chatId, text: finalText, agent_response: finalText, routed_model: 'gpt-5.4-nano', input_tokens: inputTokens, output_tokens: outputTokens, cost_usd: costUsd, intent, retrieved_kb_ids: retrievedKbIds, prompt_version_id: promptVersionId, cache_hit: false, cached_input_tokens: null, security_signal: securitySignal.security_signal, security_signal_reasoning: securitySignal.security_signal_reasoning } }];

const resp = $json;
// claude-sonnet-5 returns extended-thinking content by default: content[0] is a 'thinking'
// block (no .text field), the actual answer is the first 'text'-type block, not always at
// a fixed index - find it explicitly rather than assuming content[0].
const textBlock = (resp.content || []).find(b => b.type === 'text');
const text = (textBlock && textBlock.text) || '';
const inputTokens = (resp.usage && resp.usage.input_tokens) || 0;
const outputTokens = (resp.usage && resp.usage.output_tokens) || 0;

const pricingRows = $('Get Model Pricing').all().map(i => i.json);
const pricing = pricingRows.find(r => r.model_name === 'claude-sonnet-5') || {};
const inputPrice = Number(pricing.input_price_per_1m_tokens) || 0;
const outputPrice = Number(pricing.output_price_per_1m_tokens) || 0;
const costUsd = (inputTokens / 1e6) * inputPrice + (outputTokens / 1e6) * outputPrice;

// mirrors security/sensitive-data-detection/*.ts - same list as the input-side check in
// "Detect Language, Classify, Detect Sensitive Data" above, copied here for the output side
const PATTERNS = [
  { id: 'openai-api-key', category: 'credential', regex: /\bsk-\s?[A-Za-z0-9]{20,}\b/ },
  { id: 'aws-access-key-id', category: 'credential', regex: /\bAKIA[0-9A-Z]{16}\b/ },
  { id: 'google-api-key', category: 'credential', regex: /\bAIza[0-9A-Za-z_-]{35}\b/ },
  { id: 'bearer-token', category: 'credential', regex: /\bBearer\s+[A-Za-z0-9._-]{20,}\b/i },
  { id: 'generic-secret-assignment', category: 'credential', regex: /\b(api[_-]?key|secret|token|password|passwd|pwd)\b\s*[:=]\s*['"]?[^\s'"]{6,}['"]?/i },
  { id: 'private-key-block', category: 'credential', regex: /-----BEGIN\s+(RSA|EC|OPENSSH|DSA)?\s*PRIVATE KEY-----/ },
  { id: 'email-address', category: 'personal_identifier', regex: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/ },
  { id: 'credit-card-like-number', category: 'personal_identifier', regex: /\b(?:\d[ -]?){13,19}\b/ },
  { id: 'private-ipv4', category: 'internal_network', regex: /\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3})\b/ },
];
let flagged = false;
for (const p of PATTERNS) { if (p.regex.test(text)) { flagged = true; break; } }

const language = $('Detect Language, Classify, Detect Sensitive Data').item.json.language;
const chatId = $('Verify & Normalize').item.json.chat_id;
const parsedIntent = $('Parse Intent').item.json;

let finalText = text, intent = 'generated_tier2_' + parsedIntent.intent;
if (!text || flagged) {
  intent = flagged ? 'output_blocked_sensitive_data' : 'generation_empty';
  finalText = language === 'he'
    ? 'מצטער, לא הצלחתי לייצר תשובה בטוחה כרגע. נסה לנסח את השאלה מחדש.'
    : "Sorry, I couldn't generate a safe response right now. Try rephrasing your question.";
}

// see the matching comment in "Format Tier0 Response" for why these four fields are computed
// here rather than referenced later from Pick Best Match/Get System Prompt directly
const retrievedKbIds = JSON.stringify($('Pick Best Match').item.json.matched ? [$('Pick Best Match').item.json.matched_id] : []);
const promptVersionId = $('Get System Prompt').item.json.id;
const securitySignal = $('Parse Security Signal').item.json;

return [{ json: { chat_id: chatId, text: finalText, agent_response: finalText, routed_model: 'claude-sonnet-5', input_tokens: inputTokens, output_tokens: outputTokens, cost_usd: costUsd, intent, retrieved_kb_ids: retrievedKbIds, prompt_version_id: promptVersionId, cache_hit: false, cached_input_tokens: null, security_signal: securitySignal.security_signal, security_signal_reasoning: securitySignal.security_signal_reasoning } }];

let history = [];
try {
  const raw = $('Load Conversation History').item.json.history_raw;
  if (raw) {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) history = parsed;
  }
} catch (e) { history = []; }

const userText = $('Verify & Normalize').item.json.text;
history.push({ role: 'user', content: userText });
history.push({ role: 'assistant', content: $json.agent_response });

const MAX_TURNS = 6; // 3 exchanges
if (history.length > MAX_TURNS) history = history.slice(history.length - MAX_TURNS);

return [{
  json: {
    ...$json,
    conv_key: 'conv:' + $('Verify & Normalize').item.json.platform_user_id,
    history_json: JSON.stringify(history),
  },
}];

const intent = $json.intent;
// Bug fix (found during Phase 5 testing): intent has been suffixed with the router's
// classified sub-intent since the Phase 4 intent-router work (e.g. 'generated_tier1_question'),
// so the old exact-match check ('generated_tier1'/'generated_tier2') never matched again -
// the semantic cache silently stopped being written to. startsWith() fixes this; excluding
// '_cached' is required too, otherwise a cache-hit item (e.g.
// 'generated_tier1_question_cached') would try to re-save itself back into the cache.
const isRealGeneration = (intent.startsWith('generated_tier1') || intent.startsWith('generated_tier2')) && !intent.endsWith('_cached');
// "Check Cache Eligible" ran upstream of every branch (tier0/tier1/tier2/cache-hit alike),
// so it's a safe common ancestor here regardless of which leaf node actually produced $json.
const cacheEligible = $('Check Cache Eligible').item.json.cache_eligible;
const shouldCache = isRealGeneration && cacheEligible;

return [{ json: { ...$json, should_cache: shouldCache } }];

