INSERT INTO semantic_cache (
  query_embedding, query_text, language, intent, response_text, routed_model,
  input_tokens, output_tokens, cost_usd, retrieved_kb_ids, expires_at
)
VALUES ($1::vector, $2, $3, $4, $5, $6, $7, $8, $9, $10::jsonb, now() + interval '24 hours');

