const language = $('Detect Language, Classify, Detect Sensitive Data').item.json.language;
let text = $('Build Conversation Update').item.json.text;

// Telegram (like most bidi-aware renderers) picks a paragraph's overall direction from its
// first strong-direction character. The system prompt asks the model to open Hebrew replies
// with a Hebrew word, but that's not reliably followed (verified live - a model will still
// open with an English product name like "Claude Code" when defining it). Prepending an
// invisible Right-to-Left Mark (U+200F) forces correct RTL alignment deterministically,
// regardless of what the model actually generates - a rendering problem solved in code
// instead of left to prompt compliance.
if (language === 'he') {
